// @ts-nocheck
window.addEventListener("message",e=>{if(e.data&&"SPA_JUMP"===e.data.action){const t=e.data.url;history.pushState({},"",t),window.dispatchEvent(new PopStateEvent("popstate"))}else if(e.data&&"ClICK_JUMP"===e.data.action){const t=e.data.url,a=document.createElement("a");a.href=t,a.style.display="none",document.body.appendChild(a);const n=new MouseEvent("click",{view:window,bubbles:!0,cancelable:!0,ctrlKey:!1});a.dispatchEvent(n),a.remove()}}),window.addEventListener("message",e=>{if(e.data&&"simu_click"===e.data.action){const t=e.data.url,a=document.createElement("a");a.href=t,a.style.display="none",document.body.appendChild(a);const n=new MouseEvent("click",{view:window,bubbles:!0,cancelable:!0,ctrlKey:!1});a.dispatchEvent(n),a.remove()}});